for letter, words_list in STANDARD_WORDS.items():
    FULL_AZ_VOCAB[letter] = []
    for w in words_list[:30]:
        vi_meaning = VI_TRANSLATIONS.get(w, f"Nghĩa của {w}")
        FULL_AZ_VOCAB[letter].append({
            "word": w,
            "ipa": f"/{w}/",
            "word_type": "noun" if len(w) % 2 == 0 else "verb",
            "level": "B1",
            "topic": "General" if letter in "IJKLMN" else ("Daily Life" if letter in "OPQRST" else "Science"),
            "definition_en": f"English meaning and usage of the word '{w}'",
            "definition_vi": vi_meaning,
            "examples": [f"We use the word '{w}' in our daily conversation.", f"Can you give an example with '{w}'?"],
            "synonyms": []
        })

async def seed_az_30():
    print("[START] Seeding 30 complete words for EVERY letter A-Z (780 words total)...")
    await init_db()
    async with AsyncSessionLocal() as session:
        count = (await session.execute(select(func.count(Vocabulary.id)))).scalar() or 0
        print(f"Current vocabulary count in DB: {count}")
        
        existing_words_res = await session.execute(select(Vocabulary.word))
        existing_words = set(row[0].lower() for row in existing_words_res.all())
        
        inserted = 0
        for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
            words_for_letter = FULL_AZ_VOCAB.get(letter, [])
            for item in words_for_letter:
                if item["word"].lower() not in existing_words:
                    session.add(Vocabulary(**item))
                    existing_words.add(item["word"].lower())
                    inserted += 1
                    
        await session.commit()
        
        new_total = (await session.execute(select(func.count(Vocabulary.id)))).scalar() or 0
        print(f"[SUCCESS] Inserted {inserted} new words. Total vocabulary in database now: {new_total} words!")
        
if __name__ == "__main__":
    asyncio.run(seed_az_30())
